  const ano = new Date().getFullYear();
  const mes = String(new Date().getMonth() + 1).padStart(2, '0');
  const novoId = `${ano}${mes}-001`;

  return {
    json: {
      novo_id: novoId,
      sequencial: 1
    }
  };
}

// Extrai todos os números sequenciais dos nomes
const sequenciais = items.map(item => {
  const nome = item.json.name || '';
