  const match = nome.match(/(\d{6})-(\d{3})/);
  return match ? parseInt(match[2], 10) : 0;
});

// Pega o maior número
const maiorSequencial = Math.max(...sequenciais);

// Incrementa
const novoSequencial = maiorSequencial + 1;

// Formata com zeros à esquerda
const ano = new Date().getFullYear();
const mes = String(new Date().getMonth() + 1).padStart(2, '0');
const sequencialFormatado = String(novoSequencial).padStart(3, '0');

const novoId = `${ano}${mes}-${sequencialFormatado}`;

return {
  json: {
    novo_id: novoId,
    sequencial: novoSequencial,
    ultimo_id_encontrado: `${ano}${mes}-${String(maiorSequencial).padStart(3, '0')}`
  }
};

