let resposta = ($json["resposta"] ?? "").toString().trim();
const validator = $json["validator"];

let valido = false;
let erro = "";

// Função auxiliar para validar hora hh:mm
function validarHora(horaStr) {
    const regex = /^([0-1]?[0-9]|2[0-3]):([0-5][0-9])$/;
    return regex.test(horaStr);
}

// Colapsa múltiplos espaços em um só
function colapsarEspacos(s) {
    return s.replace(/\s+/g, ' ').trim();
}

// Capitaliza a primeira letra (preserva o resto)
function capitalizarPrimeira(s) {
    if (!s) return s;
    return s.charAt(0).toUpperCase() + s.slice(1);
}

// Corrige plural/singular de palavras comuns
function corrigirPlural(texto) {
    // Padrão: número + espaço + palavra
    return texto.replace(/(\d+)\s+(dia|ano|mes|mês|hora|minuto|segundo|semana)(?!\w)/gi, (match, num, palavra) => {
        const numero = parseInt(num, 10);
        const palavraLower = palavra.toLowerCase();

        // Mapeamento de singular/plural
        const plurais = {
            'dia': 'dias',
            'ano': 'anos',
            'mes': 'meses',
            'mês': 'meses',
            'hora': 'horas',
            'minuto': 'minutos',
            'segundo': 'segundos',
            'semana': 'semanas'
        };

        if (numero === 1) {
            // Se for 1, usa singular
            return `${num} ${palavraLower}`;
        } else {
            // Se for maior que 1, usa plural
            return `${num} ${plurais[palavraLower] || palavra}`;
        }
    });
}

// Valida data dd/MM/yyyy com checagem real de calendário
function validarEPadronizarData(dataStr) {
    const sep = dataStr.includes('/') ? '/' : (dataStr.includes('-') ? '-' : null);
    if (!sep) return null;
    const partes = dataStr.split(sep).map(p => p.trim());
    if (partes.length !== 3) return null;
    let [dd, mm, yyyy] = partes;

    if (!/^\d{1,2}$/.test(dd) || !/^\d{1,2}$/.test(mm) || !/^\d{4}$/.test(yyyy)) return null;

    const dia = parseInt(dd, 10);
    const mes = parseInt(mm, 10);
    const ano = parseInt(yyyy, 10);
    const dt = new Date(ano, mes - 1, dia);

    if (dt.getFullYear() !== ano || dt.getMonth() !== (mes - 1) || dt.getDate() !== dia) return null;

    const dd2 = String(dia).padStart(2, '0');
    const mm2 = String(mes).padStart(2, '0');
    return `${dd2}/${mm2}/${ano}`;
}

// Formata número como moeda em pt-BR (R$ 1.234,56)
function formatarMoedaPTBR(valor) {
    try {
        return valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    } catch (e) {
        const valorFormatado = valor.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
        return 'R$ ' + valorFormatado;
    }
}

// Normaliza texto: remove acentos e converte para minúsculas
function normalizarTexto(texto) {
    return texto.toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .trim();
}

// ----------------- Validações por tipo -----------------
switch (validator) {
    case "options_1_2_3":
        if (!resposta) {
            valido = false;
            erro = "A resposta não pode ficar em branco.";
        } else if (!["1", "2", "3"].includes(resposta)) {
            valido = false;
            erro = "Por favor, digite uma opção válida: 1, 2 ou 3.";
        } else {
            resposta = resposta;
            valido = true;
        }
        break;

    case "date":
        if (!resposta) {
            valido = false;
            erro = "A resposta não pode ficar em branco.";
        } else {
            const pad = validarEPadronizarData(resposta);
            if (!pad) {
                valido = false;
                erro = "Por favor, digite uma data válida no formato dd/MM/aaaa (exemplo: 25/12/2025).";
            } else {
                resposta = pad;
                valido = true;
            }
        }
        break;

      case "time":
      case "datetime":
        if (!resposta) {
            valido = false;
            erro = "A resposta não pode ficar em branco.";
            break;
        }

        const partes = resposta.split('-').map(p => p.trim());

        if (partes.length !== 2) {
            valido = false;
            erro = "Use o formato hh:mm - hh:mm.";
            break;
        }

        const [inicio, fim] = partes;

        if (!validarHora(inicio) || !validarHora(fim)) {
            valido = false;
            erro = "Informe horários válidos no formato hh:mm - hh:mm.";
            break;
        }

        const [hi, mi] = inicio.split(':').map(Number);
        const [hf, mf] = fim.split(':').map(Number);

        const inicioMin = hi * 60 + mi;
        const fimMin = hf * 60 + mf;

        // só recusa se forem iguais
        if (inicioMin === fimMin) {
            valido = false;
            erro = "Os horários não podem ser iguais.";
            break;
        }

        resposta = `${inicio} - ${fim}`;
        valido = true;
        break;


    case "text":
    case "pagamento":
        if (!resposta) {
            valido = false;
            erro = "A resposta não pode ficar em branco.";
        } else {
            resposta = colapsarEspacos(resposta);
            resposta = corrigirPlural(resposta);
            resposta = capitalizarPrimeira(resposta);
            valido = true;
        }
        break;

    case "enum:basico,avancado":
        {
            const respostaNormalizada = normalizarTexto(resposta);

            if (!resposta) {
                valido = false;
                erro = "A resposta não pode ficar em branco.";
            } else {
                const temBasico = respostaNormalizada.includes("basico");
                const temAvancado = respostaNormalizada.includes("avancado");
                const temAmbos = /ambos|dois|todos|ambas|os 2|2|os dois/.test(respostaNormalizada);

                if (temAmbos || (temBasico && temAvancado)) {
                    resposta = "Ambos";
                    valido = true;
                } else if (temBasico) {
                    resposta = "Básico";
                    valido = true;
                } else if (temAvancado) {
                    resposta = "Avançado";
                    valido = true;
                } else {
                    if (["basico", "básico"].includes(respostaNormalizada)) {
                        resposta = "Básico";
                        valido = true;
                    } else if (["avancado", "avançado"].includes(respostaNormalizada)) {
                        resposta = "Avançado";
                        valido = true;
                    } else {
                        valido = false;
                        erro = "Por favor, escolha entre: Básico, Avançado ou Ambos.";
                    }
                }
            }
        }
        break;

    case "number":
        if (!resposta) {
            valido = false;
            erro = "A resposta não pode ficar em branco.";
        } else {
            const apenas = resposta.replace(/[^\d.,-]/g, '').replace(/\s+/g, '');
            let s = apenas;
            const virgulas = (s.match(/,/g) || []).length;
            const pontos = (s.match(/\./g) || []).length;

            if (pontos > 1 && virgulas === 0) {
                s = s.replace(/\./g, '');
            } else if (virgulas > 1 && pontos === 0) {
                s = s.replace(/,/g, '');
            } else if (pontos >= 1 && virgulas >= 1) {
                s = s.replace(/\./g, '');
                s = s.replace(',', '.');
            } else {
                s = s.replace(',', '.');
            }

            const valor = parseFloat(s);
            if (isNaN(valor) || valor <= 0) {
                valido = false;
                erro = "Por favor, informe um valor válido maior que zero (exemplo: R$ 120,00 ou 120).";
            } else {
                valido = true;
                resposta = formatarMoedaPTBR(valor);
            }
        }
        break;

    case "prazo":
        if (!resposta) {
            valido = false;
            erro = "A resposta não pode ficar em branco.";
        } else {
            const match = resposta.match(/(\d+)/);
            const dias = match ? parseInt(match[1], 10) : null;

            if (!dias || dias <= 0) {
                valido = false;
                erro = "Por favor, informe a validade em dias (exemplo: 7 dias, 10 ou 15 dias).";
            } else {
                valido = true;
                resposta = dias === 1 ? "1 dia" : `${dias} dias`;
            }
        }
        break;

    default:
        if (!resposta) {
            valido = false;
            erro = "A resposta não pode ficar em branco.";
        } else {
            resposta = colapsarEspacos(resposta);
            resposta = corrigirPlural(resposta);
            resposta = capitalizarPrimeira(resposta);
            valido = true;
        }
        break;
}

return { json: { resposta, valido, erro } };

