const resposta = $json["resposta"]?.trim() || "";
let valido = false;
let erro = "";
let numero = null;
let valor = "";

// ============ FUNÇÕES AUXILIARES ============

function colapsarEspacos(s) {
    return s.replace(/\s+/g, ' ').trim();
}

function capitalizarPrimeira(s) {
    if (!s) return s;
    return s.charAt(0).toUpperCase() + s.slice(1);
}

function normalizarTexto(texto) {
    return texto.toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .trim();
}

function validarHora(horaStr) {
    const regex = /^([0-1]?[0-9]|2[0-3]):([0-5][0-9])$/;
    return regex.test(horaStr);
}

function padronizarHora(horaStr) {
    const [h, m] = horaStr.split(':');
    const hh = String(parseInt(h, 10)).padStart(2, '0');
    const mm = String(parseInt(m, 10)).padStart(2, '0');
    return `${hh}:${mm}`;
}

function validarEPadronizarData(dataStr, validarFutura = false) {
    const sep = dataStr.includes('/') ? '/' : (dataStr.includes('-') ? '-' : null);
    if (!sep) return null;

    const partes = dataStr.split(sep).map(p => p.trim());
    if (partes.length !== 3) return null;

    let [dd, mm, yyyy] = partes;
    if (!/^\d{1,2}$/.test(dd) || !/^\d{1,2}$/.test(mm) || !/^\d{4}$/.test(yyyy)) return null;

    const dia = parseInt(dd, 10);
    const mes = parseInt(mm, 10);
    const ano = parseInt(yyyy, 10);
    const dt = new Date(ano, mes - 1, dia);

    if (dt.getFullYear() !== ano || dt.getMonth() !== (mes - 1) || dt.getDate() !== dia) return null;

    // Verifica se a data é futura (se solicitado)
    if (validarFutura) {
        const hoje = new Date();
        hoje.setHours(0, 0, 0, 0); // Zera as horas para comparar apenas a data
        dt.setHours(0, 0, 0, 0);

        if (dt < hoje) {
            return "PASSADO"; // Retorna código especial para data no passado
        }
    }

    const dd2 = String(dia).padStart(2, '0');
    const mm2 = String(mes).padStart(2, '0');
    return `${dd2}/${mm2}/${ano}`;
}

function formatarMoedaPTBR(valorNum) {
    try {
        return valorNum.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    } catch (e) {
        const valorFormatado = valorNum.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
        return 'R$ ' + valorFormatado;
    }
}

function parsearValorMonetario(valorStr) {
    const apenas = valorStr.replace(/[^\d.,-]/g, '').replace(/\s+/g, '');
    let s = apenas;
    const virgulas = (s.match(/,/g) || []).length;
    const pontos = (s.match(/\./g) || []).length;

    if (pontos > 1 && virgulas === 0) {
        s = s.replace(/\./g, '');
    } else if (virgulas > 1 && pontos === 0) {
        s = s.replace(/,/g, '');
    } else if (pontos >= 1 && virgulas >= 1) {
        s = s.replace(/\./g, '');
        s = s.replace(',', '.');
    } else {
        s = s.replace(',', '.');
    }

    return parseFloat(s);
}

// ============ CONFIGURAÇÃO DE VALIDAÇÃO POR NÚMERO ============

const configuracoes = {
    "1": {
        tipo: "texto",
        descricao: "texto"
    },
    "2": {
        tipo: "texto",
        descricao: "texto"
    },
    "3": {
        tipo: "data",
        descricao: "data no formato dd/MM/aaaa"
    },
    "4": {
        tipo: "hora",
        descricao: "horário no formato hh:mm"
    },
    "5": {
        tipo: "enum",
        descricao: "Básico, Avançado ou Ambos"
    },
    "6": {
        tipo: "moeda",
        descricao: "valor em reais"
    },
    "7": {
        tipo: "prazo",
        descricao: "número de dias"
    }
};

// ============ VALIDAÇÃO PRINCIPAL ============

const padrao = /^(\d+)\s*-\s*(.+)$/;
const match = resposta.match(padrao);

if (!resposta) {
    erro = "A resposta não pode ficar em branco.";
} else if (!match) {
    erro = "O formato está incorreto. Use o modelo: '1 - Seu valor' (número, traço e valor).";
} else {
    numero = match[1].trim();
    valor = match[2].trim();

    const config = configuracoes[numero];

    if (!config) {
        erro = `O número '${numero}' não é válido. Escolha entre 1 e 7.`;
    } else if (!valor) {
        erro = "O valor após o traço não pode estar vazio.";
    } else {
        // Valida de acordo com o tipo esperado
        switch (config.tipo) {
            case "texto":
                valor = colapsarEspacos(valor);
                valor = capitalizarPrimeira(valor);
                valido = true;
                break;

            case "data":
                const dataPadronizada = validarEPadronizarData(valor, true);
                if (!dataPadronizada) {
                    erro = `O valor deve ser uma ${config.descricao} válida (exemplo: 25/12/2025).`;
                } else if (dataPadronizada === "PASSADO") {
                    erro = "A data não pode ser no passado. Informe uma data de hoje ou futura.";
                } else {
                    valor = dataPadronizada;
                    valido = true;
                }
                break;

            case "hora":
              if (!valor) {
                  erro = `O valor deve ser um ${config.descricao} (exemplo: 18:30 - 19:00).`;
                  break;
              }

              const partes = valor.split('-').map(p => p.trim());

              if (partes.length !== 2) {
                  erro = `Use o formato hh:mm - hh:mm (exemplo: 18:30 - 19:00).`;
                  break;
              }

              const [inicio, fim] = partes;

              if (!validarHora(inicio) || !validarHora(fim)) {
                  erro = `Informe horários válidos no formato hh:mm - hh:mm.`;
